CREATE FUNCTION dg_native_bill_transport_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);target text;operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;lease _dg_native_bill_worker_leases%ROWTYPE;receipt restaurant_financial_receipts%ROWTYPE;receipt_origin _dg_native_bill_receipt_origins%ROWTYPE;posting restaurant_financial_postings%ROWTYPE;remote mock_financial_operations%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;action_origin _dg_native_bill_action_origins%ROWTYPE;payload jsonb;current_runtime text;
BEGIN
 SELECT runtime_id INTO current_runtime FROM _dg_native_runtime_control WHERE id=1;
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=j->>'id';IF actual_action.kind NOT IN('bill_action','bill_fixture','bill_send','bill_query','bill_close','bill_simulate','bill_unknown','bill_stale','bill_action_blocked','bill_mock','bill_receipt') THEN RETURN NULL;END IF;
  IF actual_action.kind IN('bill_action','bill_fixture') THEN
   IF NOT EXISTS(SELECT 1 FROM _dg_native_bill_results result_value WHERE result_value.action_id=actual_action.id AND result_value.restaurant_id=actual_action.restaurant_id AND result_value.created_at=actual_action.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial human actions retain their immutable scoped result';END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM _dg_native_bill_worker_leases WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_revisions WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_mock_revisions WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_receipt_origins WHERE action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport actions have their actual immutable lease, revision or receipt';END IF;RETURN NULL;
 END IF;
 target:=CASE WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'id' WHEN TG_TABLE_NAME='restaurant_financial_postings' OR TG_TABLE_NAME='mock_financial_operations' OR TG_TABLE_NAME IN('_dg_native_bill_worker_leases','_dg_native_bill_posting_origins','_dg_native_bill_operation_revisions','_dg_native_bill_mock_revisions','_dg_native_bill_action_origins','_dg_native_bill_mock_fixture_origins') THEN j->>'operation_id' WHEN TG_TABLE_NAME='restaurant_financial_receipts' THEN j->>'operation_id' WHEN TG_TABLE_NAME IN('_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures') THEN(SELECT operation_id FROM restaurant_financial_receipts WHERE event_id=j->>'event_id') END;
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;IF operation.id IS NULL OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_origins origin WHERE origin.operation_id=operation.id AND origin.runtime_id=current_runtime) OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.operation_id=operation.id AND revision.version=operation.version AND revision.row_hash=dg_native_office_hash(to_jsonb(operation)) AND revision.created_at=operation.updated_at AND revision_action.restaurant_id=b.restaurant_id AND revision_action.resource_id=b.party_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport retains exact native request and current full row revision';END IF;
 IF operation.lease_token IS NOT NULL THEN
  SELECT * INTO lease FROM _dg_native_bill_worker_leases WHERE lease_token=operation.lease_token AND operation_id=operation.id;
  IF lease.lease_token IS NULL OR lease.runtime_id<>current_runtime OR lease.request_hash<>operation.request_hash OR lease.mode IS DISTINCT FROM operation.lease_action OR lease.expires_at IS DISTINCT FROM operation.lease_until OR lease.expires_at<>dg_native_people_iso(lease.created_at::timestamptz+interval '15 seconds') OR operation.send_attempts<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial lease keeps its fixed original deadline, request and attempt';END IF;
 ELSIF operation.lease_until IS NOT NULL OR operation.lease_action IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial lease columns clear together';END IF;
 IF TG_TABLE_NAME='_dg_native_bill_worker_leases' THEN
  SELECT * INTO lease FROM _dg_native_bill_worker_leases WHERE lease_token=j->>'lease_token';SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=lease.action_id;
  IF actual_action.kind<>'bill_'||lease.mode OR actual_action.created_at<>lease.created_at OR actual_action.restaurant_id<>b.restaurant_id OR actual_action.resource_id<>b.party_id OR lease.runtime_id<>current_runtime OR lease.request_hash<>operation.request_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial leases originate in the actual matching worker action';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text THEN
   IF operation.lease_token IS DISTINCT FROM lease.lease_token OR lease.expires_at<=dg_native_dining_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New financial lease must commit within its fixed original deadline';END IF;
   PERFORM dg_native_bill_worker_context(operation.id,lease.lease_token,true);
  END IF;
 ELSIF TG_TABLE_NAME IN('restaurant_financial_receipts','_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures','restaurant_financial_postings','_dg_native_bill_posting_origins') THEN
  IF TG_TABLE_NAME='restaurant_financial_postings' THEN SELECT * INTO posting FROM restaurant_financial_postings WHERE id=j->>'id';SELECT event_id INTO target FROM _dg_native_bill_posting_origins WHERE posting_id=posting.id;
  ELSIF TG_TABLE_NAME='_dg_native_bill_posting_origins' THEN SELECT * INTO posting FROM restaurant_financial_postings WHERE id=j->>'posting_id';target:=j->>'event_id';ELSE target:=j->>'event_id';END IF;
  SELECT * INTO receipt FROM restaurant_financial_receipts WHERE event_id=target;SELECT * INTO receipt_origin FROM _dg_native_bill_receipt_origins WHERE event_id=target;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=receipt_origin.action_id;payload:=receipt.payload::jsonb;
  IF receipt.event_id IS NULL OR receipt_origin.event_id IS NULL OR receipt.operation_id<>operation.id OR receipt_origin.runtime_id<>current_runtime OR receipt_origin.request_hash<>operation.request_hash OR receipt_origin.receipt_hash<>receipt.payload_hash OR receipt.payload_hash<>dg_native_office_hash(payload) OR actual_action.kind<>'bill_receipt' OR actual_action.body_hash<>receipt.payload_hash OR actual_action.created_at<>receipt.created_at OR receipt_origin.created_at<>receipt.created_at OR actual_action.restaurant_id<>b.restaurant_id OR actual_action.resource_id<>b.party_id OR receipt.status<>payload->>'status' OR receipt.sequence<>(payload->>'sequence')::bigint OR payload->>'operationId'<>operation.id OR payload->>'requestHash'<>operation.request_hash OR payload->>'billId'<>b.id OR payload->>'restaurantId'<>b.restaurant_id OR payload->>'merchantId'<>operation.merchant_id OR(payload->>'amountMinor')::bigint<>operation.amount_minor OR payload->>'currency'<>'CNY' OR payload->'simulated' IS DISTINCT FROM 'true'::jsonb OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_receipt_revisions revision WHERE revision.event_id=receipt.event_id AND revision.revision=(SELECT max(revision) FROM _dg_native_bill_receipt_revisions WHERE event_id=receipt.event_id) AND revision.row_hash=dg_native_office_hash(to_jsonb(receipt)) AND revision.action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial receipts retain exact verified payload, immutable origin and result revision';END IF;
  IF posting.id IS NOT NULL THEN
   IF receipt.status<>'succeeded' OR posting.operation_id<>operation.id OR posting.bill_id<>b.id OR posting.kind<>operation.kind OR posting.amount_minor<>operation.amount_minor OR posting.currency<>'CNY' OR posting.provider_id<>operation.provider_id OR posting.merchant_id<>operation.merchant_id OR posting.remote_transaction_id<>payload->>'remoteTransactionId' OR posting.environment<>'mock' OR posting.app_env<>(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR posting.created_at<>receipt.created_at OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_posting_origins origin WHERE origin.posting_id=posting.id AND origin.operation_id=operation.id AND origin.event_id=receipt.event_id AND origin.runtime_id=current_runtime AND origin.action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Immutable money postings originate only in the exact verified success, amount and environment';END IF;
  END IF;
  IF receipt.status='succeeded' AND NOT EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=operation.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every verified financial success retains a posting even if projection failed';END IF;
 ELSIF TG_TABLE_NAME IN('mock_financial_operations','_dg_native_bill_mock_revisions','_dg_native_bill_mock_fixture_origins') THEN
  SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=operation.id;SELECT revision_action.* INTO actual_action FROM _dg_native_bill_mock_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.operation_id=operation.id AND revision.sequence=remote.sequence AND revision.row_hash=dg_native_office_hash(to_jsonb(remote)) AND revision.created_at=remote.updated_at;
  IF remote.operation_id IS NULL OR remote.request_hash<>operation.request_hash OR remote.payload::jsonb IS DISTINCT FROM operation.request_payload::jsonb OR actual_action.id IS NULL OR actual_action.kind NOT IN('bill_mock','bill_fixture') OR remote.remote_operation_id<>(CASE WHEN operation.kind='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||operation.id OR remote.remote_transaction_id<>(CASE WHEN operation.kind='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||operation.id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock funds facts retain original request, matching identities and actual revision';END IF;
  IF actual_action.kind='bill_mock' AND actual_action.transaction_id=pg_current_xact_id()::text THEN PERFORM dg_native_bill_worker_context(operation.id,operation.lease_token,true);END IF;
  IF actual_action.kind='bill_fixture' AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_mock_fixture_origins origin WHERE origin.operation_id=operation.id AND origin.action_id=actual_action.id AND origin.sequence=remote.sequence AND origin.created_at=actual_action.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock fixture is an explicit single manager operation';END IF;
 ELSIF TG_TABLE_NAME='_dg_native_bill_action_origins' THEN
  SELECT * INTO action_origin FROM _dg_native_bill_action_origins WHERE action_id=j->>'action_id';SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=action_origin.action_id;
  IF actual_action.kind<>'bill_action' OR actual_action.created_at<>action_origin.created_at OR actual_action.actor_id IS DISTINCT FROM action_origin.actor_meta->>'actorId' OR actual_action.session_id IS DISTINCT FROM action_origin.actor_meta->>'sessionId' OR actual_action.focus_version IS DISTINCT FROM(action_origin.actor_meta->>'focusVersion')::bigint OR actual_action.resource_id<>b.party_id OR actual_action.restaurant_id<>b.restaurant_id OR action_origin.mode IS DISTINCT FROM operation.next_action THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial action preserves its exact current person, session, mode and scope';END IF;
  IF action_origin.mode<>'query' AND dg_native_bill_action_reason(operation.id,action_origin.mode,action_origin.actor_meta) IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit money action retains actual source through commit';END IF;
 END IF;RETURN NULL;
END;$dg$;
DO $bill_transport_final$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_financial_operations','restaurant_financial_receipts','restaurant_financial_postings','mock_financial_operations','_dg_native_bill_worker_leases','_dg_native_bill_posting_origins','_dg_native_bill_operation_revisions','_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures','_dg_native_bill_mock_revisions','_dg_native_bill_action_origins','_dg_native_bill_mock_fixture_origins','_dg_native_dining_actions'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER native_bill_transport_final AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_bill_transport_final()',table_value);END LOOP;END;$bill_transport_final$;
